'use strict';
const root=document.getElementById('game'),escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readGame=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},saveGame=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
let selected=[0,1,5],state=null,soft=readGame('tw-game-soft',false)===true,collection=readGame('tw-game-endings',[]);if(!Array.isArray(collection))collection=[];collection=[...new Set(collection.filter(id=>Object.hasOwn(survivalEndingBook,id)))];
let resumable=SurvivalEngine.restore(readGame('tw-game-save',null));document.getElementById('soft').checked=soft;
const money=n=>n.toLocaleString('ko-KR')+'원';
const speak=s=>escapeHTML(soft?s.replace(/ㅋㅋ시발/g,'ㅋㅋ아이고').replace(/씨바|시발|스바|ㅅㅂ|존나/g,'아이고'):s);
const face=p=>`<span class="avatar" style="background-position:${p.id%4*100/3}% ${Math.floor(p.id/4)*50}%" aria-hidden="true"></span>`;
function bubbles(p,lines){return `<div class="speaker">${face(p)}<div><strong>${p.name}</strong><div class="burst">${lines.map(l=>`<span>${speak(l)}</span>`).join('')}</div></div></div>`;}
function persist(){saveGame('tw-game-save',state);}
function lobby(){resumable=SurvivalEngine.restore(readGame('tw-game-save',null));state=null;root.innerHTML=`<section class="intro"><p class="eyebrow">친구 셋 + 총무 하나 · 선택형 생존게임</p><h1>개테천<br><em>모임 대작전</em><span>오늘도 무사히 집에 갈 수 있을까?</span></h1><p>예산은 12만 원. 갈 곳은 많은데 의견은 더 많다.<br>지갑 분실, 정산 대치, 재대결과 폭우.<br>예상 밖의 사건 속에서 모임을 지켜라.</p><p class="muted">공동 예산을 넘긴 지출은 총무 개인 결제로 남습니다.</p><div class="rules"><span>₩ 공동 예산</span><span>♥ 체력</span><span>🍚 배부름</span><span>✦ 분위기</span></div></section><section class="party"><div class="section-head"><h2>오늘 같이 나갈 친구</h2><span id="count">${selected.length} / 3</span></div><p class="muted">선택의 결과는 고른 뒤에 드러납니다. 아래는 창작 대사 샘플.</p><div class="cast">${survivalCast.map(p=>`<button class="cast-card ${selected.includes(p.id)?'selected':''}" data-person="${p.id}" aria-pressed="${selected.includes(p.id)}">${face(p)}<strong>${p.name}</strong><small>${p.tag}</small><span class="sample">${p.sample.map(speak).join('<br>')}</span></button>`).join('')}</div><div class="launch"><button class="primary" id="start" ${selected.length!==3?'disabled':''}>이 멤버로 출발 →</button>${resumable?'<button id="resume">지난 모임 이어하기</button>':''}</div><p class="muted">수집한 엔딩 ${new Set(collection).size} / ${Object.keys(survivalEndingBook).length} · 한 판 약 5분</p><details><summary>엔딩 도감</summary><div class="ending-book">${Object.entries(survivalEndingBook).map(([id,e])=>`<span class="${collection.includes(id)?'unlocked':''}">${collection.includes(id)?e[2]+' '+e[0]:'🔒 아직 만나지 못한 결말'}</span>`).join('')}</div></details></section>`;root.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{let id=Number(b.dataset.person);if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<3)selected.push(id);else{document.getElementById('count').textContent='3명까지 선택 · 한 명을 먼저 해제';return;}lobby();});document.getElementById('start').onclick=()=>{state=SurvivalEngine.create(selected);persist();render();window.scrollTo(0,0)};const resume=document.getElementById('resume');if(resume)resume.onclick=()=>{state=resumable;selected=[...state.party];render();window.scrollTo(0,0)};}
function stats(){return `<div class="stats"><div class="cash"><span>네 사람의 공동 예산</span><strong>${money(state.budget)}</strong>${state.debt?`<small class="debt">총무 개인 결제 ${money(state.debt)}</small>`:''}</div>${[['energy','체력','♥'],['fullness','배부름','🍚'],['mood','분위기','✦']].map(([k,n,i])=>`<div class="meter ${state[k]<25?'danger':''}"><span>${i} ${n}<b>${state[k]}</b></span><progress max="100" value="${state[k]}" aria-label="${n}"></progress></div>`).join('')}</div>`;}
function transcript(endingMode=false){return SurvivalEngine.dialogue(state,endingMode).map(t=>bubbles(survivalCast[t.id],t.lines)).join('');}
function members(){return `<div class="member-states">${state.party.map(id=>`<span>${face(survivalCast[id])}<b>${survivalCast[id].nick}</b><small>${state.personal[id]<30?'말수가 줄었다':state.personal[id]>85?'텐션 올라옴':state.personal[id]>65?'꽤 즐기는 중':'눈치 보는 중'}</small></span>`).join('')}<div class="tension ${state.tension>=40?'hot':''}">갈등 ${state.tension}<progress max="100" value="${state.tension}" aria-label="갈등"></progress></div></div>`;}
function recap(){return `<details><summary>오늘의 선택과 사건 기록 (${state.actions.length})</summary><ol>${state.history.map(h=>{const sc=survivalScenes.find(x=>x.id===h.scene),c=sc.choices.find(x=>x.id===h.choice),incident=state.incidents.find(i=>i.step===survivalScenes.indexOf(sc)+1);return `<li><small>${sc.time} · ${sc.location}</small><br>${c.label}${incident?`<aside>⚡ ${survivalDilemmas[incident.id].title}<br><small>↳ ${survivalDilemmas[incident.id].choices.find(c=>c.id===incident.choice).label}</small></aside>`:''}</li>`}).join('')}</ol></details>`;}
function render(){if(!state)return lobby();const ended=SurvivalEngine.ending(state);if(state.phase==='end'){if(!collection.includes(ended[0])){collection.push(ended[0]);saveGame('tw-game-endings',collection);}root.innerHTML=`<section class="ending ending-${ended[0]}"><p class="eyebrow">모임 종료 · ENDING ${collection.length} / ${Object.keys(survivalEndingBook).length}</p><div class="end-icon">${ended[3]}</div><h1>${ended[1]}</h1><p class="epilogue">${ended[2]}</p><div class="ending-causes">${state.incidents.map(i=>`<span>${survivalDilemmas[i.id].icon} ${survivalDilemmas[i.id].choices.find(c=>c.id===i.choice).label}</span>`).join('')}</div>${stats()}${members()}<section class="chat final-chat"><div class="chat-head"><b>해산 뒤 단톡방</b><span>창작 후일담</span></div>${transcript(true)}</section>${recap()}<div class="launch"><button class="primary" id="again">같은 멤버로 다른 하루</button><button id="party">멤버 바꾸기 · 엔딩 도감</button><button id="share">결과 복사</button></div><p id="copy-status" role="status"></p></section>`;document.getElementById('again').onclick=()=>{state=SurvivalEngine.create(state.party);persist();render();window.scrollTo(0,0)};document.getElementById('party').onclick=lobby;document.getElementById('share').onclick=async()=>{const text=`개테천 모임 대작전: ${ended[1]}\n${state.party.map(id=>survivalCast[id].name).join(' · ')}\n남은 예산 ${money(state.budget)} / 갈등 ${state.tension}\nhttps://inzae1.github.io/theme-wiki/game.html`;try{await navigator.clipboard.writeText(text);document.getElementById('copy-status').textContent='결과를 복사했습니다.'}catch{document.getElementById('copy-status').textContent=text}};return;}
const dilemma=state.phase==='dilemma',crisisReaction=state.phase==='dilemmaReaction',reaction=state.phase==='reaction'||crisisReaction,scene=survivalScenes[Math.min(6,state.phase==='reaction'?state.step-1:state.step)],incident=(dilemma||crisisReaction)?SurvivalEngine.incident(state):null,last=crisisReaction?state.incidents.at(-1):state.history.at(-1),choice=crisisReaction?incident.choices.find(c=>c.id===last.choice):state.phase==='reaction'?survivalScenes[state.step-1].choices.find(c=>c.id===last.choice):null,title=incident?.title||scene.title,intro=incident?.intro||scene.intro;
root.innerHTML=`<div class="play-top"><span>${incident?'⚡ 돌발 사건':`ROUND ${state.phase==='reaction'?state.step:state.step+1} / 7`}</span><small>일정 지연 ${state.delay}분</small><button id="back">멤버 선택</button></div><div class="steps" aria-hidden="true">${survivalScenes.map((s,i)=>`<span class="${i<state.step?'done':i===state.step?'current':''}"></span>`).join('')}</div>${stats()}${members()}<div class="play-grid"><section class="scene ${incident?'crisis':''}"><p class="eyebrow">${incident?incident.location:gameClock(scene.time)+' · '+scene.location}</p><h1>${title}</h1><p>${intro}</p><div class="scene-art" aria-hidden="true">${incident?.icon||{arrive:'🚉',food:'🍚',wait:'☕',move:'🚶',activity:'🎮',dinner:'🍜',home:'🌙'}[scene.id]}<span>${incident?'예상에 없던 갈림길':'개테천의 하루'}</span></div>${reaction?`<div class="chosen"><small>총무의 선택</small><strong>${choice.label}</strong><p>지출 ${money(choice.cost||0)}${crisisReaction?'':` · 취향에 따른 분위기 ${signed(last.affinity)}`}</p>${crisisReaction?`<p class="outcome">${choice.text}</p>${choice.flag==='rematch'?`<p class="match-result">${state.flags.includes('won')?'역전승! 결과 화면이 저장됐다.':'또 졌다. 설욕은 다음 모임으로.'}</p>`:''}`:''}</div><button class="primary next" id="next">${ended?'오늘의 결말 보기':state.pending?'⚡ 그런데, 잠깐…':'이후 상황 보기 →'}</button>`:`<div class="choices">${(incident||scene).choices.map(ch=>`<button data-choice="${ch.id}"><strong>${ch.label}</strong></button>`).join('')}</div>`}</section><section class="chat"><div class="chat-head"><b>개테천 · 오늘 모임</b><span>4명</span></div><p class="chat-date">${incident?'평소와 달라진 대화':reaction?'선택 뒤의 대화':'지금 상황에 대한 이야기'}</p>${transcript()}<div class="chat-note">실제 말투를 참고한 창작 대화 · 같은 멤버도 다른 반응</div></section></div>${recap()}`;
document.getElementById('back').onclick=lobby;if(reaction)document.getElementById('next').onclick=()=>{state=SurvivalEngine.next(state);persist();render();window.scrollTo(0,0)};else root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{state=dilemma?SurvivalEngine.resolve(state,b.dataset.choice):SurvivalEngine.choose(state,b.dataset.choice);persist();render();document.querySelector('.chat').scrollIntoView({block:'nearest',behavior:'smooth'})});}
function gameClock(time){const [h,m]=time.split(':').map(Number),total=h*60+m+state.delay;return String(Math.floor(total/60)%24).padStart(2,'0')+':'+String(total%60).padStart(2,'0');}
function signed(n){return (n>0?'+':'')+n;}
document.getElementById('soft').onchange=e=>{soft=e.target.checked;saveGame('tw-game-soft',soft);render()};lobby();
